# 卡片底部第 1 个标签：GVP 最近喷发年 → 文字（≤24 字符）
def eruption_tag(year, evidence):
    if year is None:
        if evidence == "Eruption Observed":
            return "Eruption observed"
        return "Eruption date unknown" if evidence == "Evidence Credible" else "Possible recent activity"
    if year < 0:
        return f"Last eruption {-year} BCE"
    if year < 1000:
        return f"Last eruption c. {year} CE"
    return f"Last eruption {year}"
